local pJvV=""
local Hgcd="iKfbyPQE"
local kRW=""
local b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
pJvV=pJvV:gsub("[^"..b.."]","")
for tkr=1,#pJvV,4 do
local a,c,d,e=b:find((pJvV:sub(tkr,tkr3).."===="),1)
local n=a and((a-1)*262144+(c-1)*4096+(d-1)*64+(e-1))or 0
kRW=kRW..string.char(math.floor(n/65536)%256,math.floor(n/256)%256,n%256)
end
kRW=kRW:gsub("\0+$","")
local Tim=""
for tkr=1,#kRW do
local c=kRW:byte(tkr)
local k=Hgcd:byte((tkr-1)%#Hgcd+1)
Tim=Tim..string.char(c~k)
end
local f,h=loadstring(Tim)
if f then local o,e=pcall(f)
if not o then warn("[Miles-HUB]",e) end
else warn("[Miles-HUB] compile:",h) end